const query = $input.first().json.query ?? {};

const statusPermitidos = ['aberto', 'em_atendimento', 'aguardando_cliente', 'resolvido', 'cancelado'];
const prioridadesPermitidas = ['baixa', 'media', 'alta'];

const status = query.status?.trim() || null;
const prioridade = query.prioridade?.trim() || null;

if (!status && !prioridade) {
  return [{ json: {
    valid: false,
    status: 400,
    erro: 'Informe ao menos um filtro: status ou prioridade',
    codigo: 'FILTRO_OBRIGATORIO'
  } }];
}

if (status && !statusPermitidos.includes(status)) {
  return [{ json: {
    valid: false,
    status: 400,
    erro: 'Status inválido. Use: aberto, em_atendimento, aguardando_cliente, resolvido ou cancelado',
    codigo: 'STATUS_INVALIDO'
  } }];
}

if (prioridade && !prioridadesPermitidas.includes(prioridade)) {
  return [{ json: {
    valid: false,
    status: 400,
    erro: 'Prioridade inválida. Use: baixa, media ou alta',
    codigo: 'PRIORIDADE_INVALIDA'
  } }];
}

return [{ json: { valid: true, status, prioridade } }];

const { status, prioridade } = $input.first().json;
const filtros = { status, prioridade };

const base = 'SELECT id, protocolo, cliente_id, titulo, descricao, prioridade, status, criado_em, atualizado_em FROM tickets';

let query;
if (status && prioridade) {
  query = `${base} WHERE status = '${status}' AND prioridade = '${prioridade}' ORDER BY criado_em DESC`;
} else if (status) {
  query = `${base} WHERE status = '${status}' ORDER BY criado_em DESC`;
} else {
  query = `${base} WHERE prioridade = '${prioridade}' ORDER BY criado_em DESC`;
}

return [{ json: { query, filtros } }];

const tickets = $input.all()
  .map(item => item.json)
  .filter(row => row.id);

const filtros = $('Montar_query').first().json.filtros;

return [{ json: {
  total: tickets.length,
  filtros,
  tickets
} }];
